import math
import re

# All coordinates are retained; the tolerance only accounts for the stated
# rounding to five decimal places.
path = """
M 24.38698,-19.9365 L 29.3405,-17.62663
M 0.0,7.0 L 0.0,5.46
M 10.35209,0.0 L 10.35209,-7.0986
M 20.49493,-28.84999 L 17.75636,-22.97711
M 20.49493,-21.75139 L 24.38698,-19.9365
M 18.29129,-17.02568 L 20.49493,-21.75139
M 17.75636,-22.97711 L 15.16487,-17.41963
M 10.35209,-7.0986 L 0.0,-7.0986
M 22.10067,8.68911 L 19.34832,10.61633
M 2.5205,-5.64339 L 6.14757,-3.5493
M 10.35209,-4.68508 L 10.35209,0.0
M 10.35209,-7.0986 L 10.35209,-4.68508
M 20.49493,-25.44266 L 20.49493,-28.84999
M 0.0,-7.0986 L 2.5205,-5.64339
M 6.14757,-3.5493 L 2.33608,-1.34873
M 24.85302,6.76189 L 22.10067,8.68911
M 15.93065,-11.96326 L 17.25429,-14.80182
M 20.49493,-21.75139 L 20.49493,-25.44266
M 19.34832,10.61633 L 17.21983,12.10671 L 11.74658,15.93912
M 10.35209,1.96 L 10.35209,3.3712
M 0.0,5.46 L 0.0,0.0
M 4.03732,0.0 L 10.35209,0.0
M 10.35209,7.0 L 7.55703,7.0
M 10.35209,0.0 L 15.93065,-11.96326
M 10.35209,3.3712 L 10.35209,7.0
M 2.33608,-1.34873 L 0.0,0.0
M 34.99586,-14.98949 L 24.85302,6.76189
M 15.16487,-17.41963 L 10.35209,-7.0986
M 11.74658,15.93912 L 11.17484,9.40408
M 0.0,0.0 L 4.03732,0.0
M 11.17484,9.40408 L 10.79637,5.0782
M 29.3405,-17.62663 L 34.99586,-14.98949
M 10.35209,0.0 L 10.35209,1.96
M 10.79637,5.0782 L 10.35209,0.0
M 7.55703,7.0 L 0.0,7.0
M 17.25429,-14.80182 L 18.29129,-17.02568
"""

EPS = 0.0001
ANG = 0.00002

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def norm(a):
    return math.hypot(*a)

def parallel(a, b):
    return abs(cross(a, b)) <= ANG * norm(a) * norm(b)

def perpendicular(a, b):
    return abs(dot(a, b)) <= ANG * norm(a) * norm(b)

def on_segment(p, a, b):
    v, w = sub(b, a), sub(p, a)
    length = norm(v)
    return (abs(cross(v, w)) <= EPS * length
            and -EPS * length <= dot(w, v) <= dot(v, v) + EPS * length)

segments = []
current = None
for command, x, y in re.findall(r"([ML])\s+(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)", path):
    p = (float(x), float(y))
    if command == "L":
        segments.append((current, p))
    current = p

points = []
def register(p):
    for i, q in enumerate(points):
        if norm(sub(p, q)) <= EPS:
            return i
    points.append(p)
    return len(points) - 1

for a, b in segments:
    register(a)
    register(b)

# Split at every crossing, endpoint, and overlap endpoint.
for i, (a, b) in enumerate(segments):
    r = sub(b, a)
    for c, d in segments[i + 1:]:
        s = sub(d, c)
        den = cross(r, s)
        if parallel(r, s):
            continue
        t = cross(sub(c, a), s) / den
        u = cross(sub(c, a), r) / den
        if (-EPS / norm(r) <= t <= 1 + EPS / norm(r)
                and -EPS / norm(s) <= u <= 1 + EPS / norm(s)):
            register((a[0] + t * r[0], a[1] + t * r[1]))

edges = set()
for a, b in segments:
    v = sub(b, a)
    ids = [i for i, p in enumerate(points) if on_segment(p, a, b)]
    ids.sort(key=lambda i: dot(sub(points[i], a), v))
    for u, w in zip(ids, ids[1:]):
        if u != w:
            edges.add(tuple(sorted((u, w))))

graph = {i: set() for i in range(len(points))}
for u, v in edges:
    graph[u].add(v)
    graph[v].add(u)

# Remove only degree-two points lying on a straight side.
changed = True
while changed:
    changed = False
    for v in list(graph):
        if len(graph[v]) == 2:
            a, b = sorted(graph[v])
            va, vb = sub(points[a], points[v]), sub(points[b], points[v])
            if parallel(va, vb) and dot(va, vb) < 0:
                graph[a].remove(v)
                graph[b].remove(v)
                graph[a].add(b)
                graph[b].add(a)
                del graph[v]
                changed = True
                break

# Enumerate all simple cycles, not just faces. The minimum vertex starts each
# cycle, and one orientation is retained.
cycles = []
for start in sorted(graph):
    def dfs(route, visited):
        v = route[-1]
        for w in sorted(graph[v]):
            if w == start:
                if len(route) >= 3 and route[1] < route[-1]:
                    cycles.append(tuple(route))
            elif w > start and w not in visited:
                dfs(route + [w], visited | {w})
    dfs([start], {start})

def corners(poly):
    poly = list(poly)
    changed = True
    while changed and len(poly) > 3:
        changed = False
        for i in range(len(poly)):
            a, b, c = poly[i - 1], poly[i], poly[(i + 1) % len(poly)]
            u, v = sub(b, a), sub(c, b)
            if parallel(u, v) and dot(u, v) > 0:
                poly.pop(i)
                changed = True
                break
    return poly

def strictly_inside(p, poly):
    for a, b in zip(poly, poly[1:] + poly[:1]):
        if on_segment(p, a, b):
            return False
    inside = False
    for a, b in zip(poly, poly[1:] + poly[:1]):
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if x > p[0]:
                inside = not inside
    return inside

def classify(poly):
    n = len(poly)
    sides = [sub(poly[(i + 1) % n], poly[i]) for i in range(n)]
    lengths = [norm(v) for v in sides]
    turns = [cross(sides[i - 1], sides[i]) for i in range(n)]
    convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)
    equal_sides = max(lengths) - min(lengths) <= EPS
    equal_angles = max(
        dot(sides[i - 1], sides[i]) /
        (lengths[i - 1] * lengths[i]) for i in range(n)
    ) - min(
        dot(sides[i - 1], sides[i]) /
        (lengths[i - 1] * lengths[i]) for i in range(n)
    ) <= ANG
    regular = convex and equal_sides and equal_angles

    if n == 3:
        right = any(perpendicular(sides[i - 1], sides[i]) for i in range(n))
        return {4 if right else 3}
    if n == 4:
        p1, p2 = parallel(sides[0], sides[2]), parallel(sides[1], sides[3])
        rectangle = p1 and p2 and perpendicular(sides[0], sides[1])
        if rectangle:
            return {2 if equal_sides else 1}
        if p1 and p2:
            return {5}
        if convex and p1 != p2:
            return {6}
    if n == 5:
        return {9 if regular else (7 if convex else 8)}
    if n == 6 and regular:
        return {10}
    return set()

found = set()
witnesses = {}
for cycle in cycles:
    poly = corners([points[i] for i in cycle])
    kinds = classify(poly)
    if not kinds:
        continue

    # The arrangement is split at every intersection, so an atomic edge's
    # midpoint decides whether that entire edge is inside the polygon.
    # Reject shapes with additional drawn lines in their interior.
    if any(strictly_inside(
        ((points[u][0] + points[v][0]) / 2,
         (points[u][1] + points[v][1]) / 2), poly
    ) for u, v in edges):
        continue

    found.update(kinds)
    for kind in kinds:
        witnesses.setdefault(kind, poly)

options = {
    "A": {1, 7, 3}, "B": {1, 8}, "C": {7, 9}, "D": {5},
    "E": {1, 5, 7, 8}, "F": {1, 5, 7, 8, 4, 6},
    "G": {7, 8, 2, 10}, "H": {1, 8, 9}, "I": {5, 3},
    "J": {1}, "K": {7, 8}, "L": {5, 8}, "M": {5, 2},
    "N": {1, 8, 2, 4, 9}, "O": {1, 5, 7, 8, 10},
    "P": {1, 7, 8, 6},
}
print("Exhaustively enumerated simple cycles:", len(cycles))
print("Computed shape types:", sorted(found))
print("Submitted E contains:", sorted(options["E"]))
for kind in sorted(witnesses):
    print("Witness for type", kind, ":", witnesses[kind])
print("Matching options:", [k for k, v in options.items() if v == found])
print("CHECK PASS" if found == options["E"] else "CHECK FAIL")
